const deferred = () => { let resolve; const promise = new Promise(yes => { resolve = yes; }); return { promise, resolve }; };
const api = async (context, path, method = 'GET', body) => {
  const response = await context.request.fetch(base + '/api' + path, { method, ...(body === undefined ? {} : { data: body }) });
  const value = await response.json(); assert(response.ok(), `${method} ${path}: ${response.status()} ${JSON.stringify(value)}`); return value;
};
const community = (context, path, method = 'GET', body) => api(context, '/community' + path, method, body);
const register = async (context, slug, nickname, interactive = true) => {
  const email = `follower-invites-${slug}@example.test`;
  const { user } = await api(context, '/auth/register', 'POST', { email, password, name: '账户 ' + slug });
  if (interactive) await api(context, '/sync', 'POST', { changes: [{ id: 'profile', kind: 'profile', data: { age: 25, height: 172, weight: 68, sex: 'male', goal: 'maintain', activity: 1.375 }, baseVersion: 0 }] });
  const { profile } = await community(context, '/me/profile', 'PATCH', { nickname }); return { ...user, nickname, email, accountNumber: profile.accountNumber };
};
const newContext = async () => { const context = await browser.newContext({ reducedMotion: 'reduce', viewport: { width: 1440, height: 1000 } }); contexts.push(context); return context; };
const newPage = async context => {
  const page = await context.newPage(); page.setDefaultTimeout(15000); page.on('pageerror', error => errors.push(error.message));
  page.on('request', value => { const url = new URL(value.url()); if (url.pathname === '/api/community/me/followers') requests.push({ path: url.pathname + url.search, method: value.method() }); });
  return page;
};
const route = (page, hash) => page.evaluate(hash => { location.hash = hash; }, hash);
const action = (page, name) => page.locator(`[data-cm="${name}"]`);
const source = (page, name) => page.locator(`.cm-group-invite-tabs [data-cm="group-invite-source"][data-source="${name}"]`);
